1	//! MPSC v2 ring: v1's claim and seq protocol over SPSC v3's
2	//! segments, per the design doc's "MPSC v2: ring of segments"
3	//! section. A sibling of v0 and v1 under the same module layout,
4	//! so the three measure side by side, and neither of them
5	//! changes for it.
6	//!
7	//! - Segments: up to [`MAX_SEGMENTS`] taken from the application's
8	//!   [`Pool`] at [`MpscRing::init`], each a header of three lines
9	//!   then `seg_capacity` slots opening with the seq word, as
10	//!   `spsc::v3` lays its segments out. Nothing allocates while the
11	//!   ring runs, and there is no `attach`.
12	//! - Words: 32 bits everywhere. A position is [`SEQ_BITS`] wide,
13	//!   and the slot word holds v1's values in those bits, claimable
14	//!   at `pos`, committed at `pos + M + 1`, released at `pos + M`,
15	//!   with v1's tombstone at bit 31. The claim word packs the
16	//!   current segment over the next position, and a seal packs
17	//!   MOVED, the next segment, and the end position the same way.
18	//! - The claim word is the seal: every producer claims as v1
19	//!   claims, and a stale view fails the CAS, so no claim lands in
20	//!   a segment the ring has left.
21	//! - A producer at a full segment takes a free one by setting its
22	//!   bit in the in-use word, moves the claim word to it, and seals
23	//!   the old segment's header. The consumer reads the seal only when a
24	//!   slot is neither committed nor tombstoned, so its fast path
25	//!   is v1's one load.
26	//! - Gated with the rest of `mpsc` on `target_has_atomic = "32"`.
27	//! - How to use it, from a pool to several producer threads, is
28	//!   the user guide, `notes/user-guide.md`, and what happens to
29	//!   the segments over a run is the design note's Segment
30	//!   lifecycle subsection, both with `examples/guide_mpsc_v2.rs`.
31	
32	use core::marker::PhantomData;
33	use core::mem::size_of;
34	use core::sync::atomic::{AtomicU32, Ordering};
35	
36	use crate::spsc::v3::{check_body_type, seq_of, validate_geometry};
37	use crate::{CACHE_LINE_SIZE, CacheAligned, Error, Pool};
38	
39	mod consumer;
40	mod producer;
41	
42	pub use crate::spsc::v2::SLOT_HEADER_BYTES;
43	pub use crate::spsc::v3::{MAX_SEG_CAPACITY, MAX_SEGMENTS, SEQ_BITS};
44	pub use consumer::{MpscConsumer, MpscReadSlot};
45	pub use producer::MpscProducer;
46	
47	/// The position's bits within a word.
48	const SEQ_MASK: u32 = (1 << SEQ_BITS) - 1;
49	
50	/// Where a segment number sits in a word, above the position.
51	const SEG_SHIFT: u32 = SEQ_BITS;
52	
53	/// A segment number, once shifted down.
54	const SEG_MASK: u32 = MAX_SEGMENTS - 1;
55	
56	/// Set in a seal word: the segment ended at the word's position,
57	/// and the ring went on in the word's segment.
58	const MOVED: u32 = 1 << 31;
59	
60	/// Tombstone offset in a slot word: an unwound `send_with`
61	/// commits `pos + M + 1 + TOMBSTONE`, which the consumer
62	/// releases without delivering, as v1's.
63	///
64	/// - Distinct from every value a side can see: the position
65	///   bits of a committed word never carry bit 31.
66	pub(crate) const TOMBSTONE: u32 = 1 << 31;
67	
68	const _: () = assert!(SEG_SHIFT + MAX_SEGMENTS.trailing_zeros() <= 31);
69	
70	/// The word naming segment `seg` and position `pos`.
71	#[inline]
72	fn word(seg: u32, pos: u32) -> u32 {
73	    (seg << SEG_SHIFT) | seq_of(pos)
74	}
75	
76	/// The segment a word names.
77	#[inline]
78	fn word_seg(w: u32) -> u32 {
79	    (w >> SEG_SHIFT) & SEG_MASK
80	}
81	
82	/// The position a word names.
83	#[inline]
84	fn word_pos(w: u32) -> u32 {
85	    w & SEQ_MASK
86	}
87	
88	/// The three lines at the front of every segment.
89	///
90	/// - Only segment 0's `claim` and `in_use` lines are used, so
91	///   every segment has the same layout. The claim word is the
92	///   contended line and has it alone.
93	#[repr(C)]
94	struct SegmentHeader {
95	    /// The seal: MOVED, the next segment, and the end position,
96	    /// stored by the producer that moved the ring on, cleared by
97	    /// the producer that next takes this segment, and read by
98	    /// the consumer when a slot is not committed.
99	    seal: CacheAligned<AtomicU32>,
100	    /// Segment 0: the current segment and the next position to
101	    /// claim, CAS-claimed by every producer.
102	    claim: CacheAligned<AtomicU32>,
103	    /// Segment 0: the in-use word and the switch count, both
104	    /// touched on the switch path only.
105	    in_use: CacheAligned<InUseLine>,
106	}
107	
108	/// The in-use line's two words.
109	#[repr(C)]
110	struct InUseLine {
111	    /// One bit per segment, set while the segment is in use. A
112	    /// producer takes a free segment with a `fetch_or` that
113	    /// succeeds only where the bit was clear, and the consumer
114	    /// gives one back with a `fetch_and`. v3's pair of parity
115	    /// words is sound for one producer and not for several: two
116	    /// producers with views one store apart can agree a segment
117	    /// in use is free.
118	    in_use: AtomicU32,
119	    /// The ring's count of producer switches.
120	    switches: AtomicU32,
121	}
122	
123	const _: () = assert!(size_of::<SegmentHeader>() == 3 * CACHE_LINE_SIZE);
124	
125	/// Bytes a segment needs: its header lines, then the slots.
126	///
127	/// - The pool handed to [`MpscRing::init`] needs buffers at least
128	///   this large.
129	/// - Computed in u64 for the same 32-bit wrap reason as the
130	///   rings' region sizes.
131	pub fn segment_size(slot_size: u32, seg_capacity: u32) -> u64 {
132	    size_of::<SegmentHeader>() as u64 + slot_size as u64 * seg_capacity as u64
133	}
134	
135	/// A ring's geometry and its segments' addresses, the state
136	/// every endpoint starts from.
137	///
138	/// - Borrowed on every path, never copied: v3's fast-path
139	///   finding.
140	#[derive(Clone, Copy)]
141	struct Segments {
142	    /// The slot array of each segment, `seg_count` of them.
143	    slots: [*mut u8; MAX_SEGMENTS as usize],
144	    /// The header of each segment, `seg_count` of them.
145	    headers: [*const SegmentHeader; MAX_SEGMENTS as usize],
146	    /// Slot size N in bytes.
147	    slot_size: u32,
148	    /// Segment depth M, a power of two.
149	    capacity: u32,
150	    /// Slot-position mask (`capacity - 1`).
151	    mask: u32,
152	    /// Segments in the ring.
153	    seg_count: u32,
154	    /// `capacity + 1`, precomputed: the commit value is
155	    /// `pos + M + 1`, one add on the hot path.
156	    commit_add: u32,
157	}
158	
159	impl Segments {
160	    /// The seq word of the slot at position `idx` in segment
161	    /// `seg`.
162	    #[inline]
163	    fn seq(&self, seg: u32, idx: u32) -> &AtomicU32 {
164	        let slot = crate::slot_ptr(self.slots[seg as usize], idx, self.mask, self.slot_size);
165	        // SAFETY: seg < seg_count and the slot is in bounds of
166	        // that segment's buffer, line-aligned, so its first word
167	        // is an aligned AtomicU32, shared atomic state by design.
168	        unsafe { &*(slot as *const AtomicU32) }
169	    }
170	
171	    /// The body of the slot at position `idx` in segment `seg`,
172	    /// behind its [`SLOT_HEADER_BYTES`].
173	    #[inline]
174	    fn body(&self, seg: u32, idx: u32) -> *mut u8 {
175	        let slot = crate::slot_ptr(self.slots[seg as usize], idx, self.mask, self.slot_size);
176	        // SAFETY: SLOT_HEADER_BYTES < CACHE_LINE_SIZE <= slot_size,
177	        // so the body starts inside the slot.
178	        unsafe { slot.add(SLOT_HEADER_BYTES) }
179	    }
180	
181	    /// Segment `seg`'s header.
182	    #[inline]
183	    fn header(&self, seg: u32) -> &SegmentHeader {
184	        // SAFETY: seg < seg_count, and the header is the front of
185	        // a buffer that lives as long as the pool region the ring
186	        // borrows from.
187	        unsafe { &*self.headers[seg as usize] }
188	    }
189	
190	    /// Segment `seg`'s seal word.
191	    #[inline]
192	    fn seal(&self, seg: u32) -> &AtomicU32 {
193	        &self.header(seg).seal
194	    }
195	
196	    /// The claim word.
197	    #[inline]
198	    fn claim(&self) -> &AtomicU32 {
199	        &self.header(0).claim
200	    }
201	
202	    /// The in-use word.
203	    #[inline]
204	    fn in_use(&self) -> &AtomicU32 {
205	        &self.header(0).in_use.in_use
206	    }
207	
208	    /// The ring's count of producer switches.
209	    #[inline]
210	    fn switches(&self) -> &AtomicU32 {
211	        &self.header(0).in_use.switches
212	    }
213	
214	    /// Every segment's bit.
215	    #[inline]
216	    fn all(&self) -> u32 {
217	        if self.seg_count == MAX_SEGMENTS {
218	            u32::MAX
219	        } else {
220	            (1 << self.seg_count) - 1
221	        }
222	    }
223	}
224	
225	/// A ring of segments over the application's pool, split into
226	/// the producer and consumer handles with [`MpscRing::split`].
227	pub struct MpscRing<'a> {
228	    /// Geometry and segment addresses.
229	    segs: Segments,
230	    _region: PhantomData<&'a [u8]>,
231	}
232	
233	impl<'a> MpscRing<'a> {
234	    /// Take `seg_count` segments from `pool` and initialize each
235	    /// as an empty ring of `seg_capacity` slots of `slot_size`
236	    /// bytes.
237	    ///
238	    /// - `slot_size`: N bytes per slot, a [`CACHE_LINE_SIZE`]
239	    ///   multiple, of which [`SLOT_HEADER_BYTES`] are the crate's.
240	    /// - `seg_capacity`: M slots per segment, a power of two up to
241	    ///   [`MAX_SEG_CAPACITY`], 1 included.
242	    /// - `seg_count`: 1 to [`MAX_SEGMENTS`].
243	    /// - The pool's buffers must hold [`segment_size`], else
244	    ///   [`Error::TooSmall`]. A pool without `seg_count` free
245	    ///   buffers gives [`Error::Exhausted`], with the buffers
246	    ///   taken so far freed.
247	    /// - The pool is borrowed only here. The segments stay
248	    ///   allocated for the life of the pool region, as a
249	    ///   [`BufSlot`](crate::BufSlot) dropped without `free` does.
250	    pub fn init(
251	        pool: &mut Pool<'a>,
252	        slot_size: u32,
253	        seg_capacity: u32,
254	        seg_count: u32,
255	    ) -> Result<Self, Error> {
256	        validate_geometry(slot_size, seg_capacity, seg_count)?;
257	        if (pool.buf_size() as u64) < segment_size(slot_size, seg_capacity) {
258	            return Err(Error::TooSmall);
259	        }
260	        let mut taken: [Option<crate::BufSlot<'a, [u8]>>; MAX_SEGMENTS as usize] =
261	            core::array::from_fn(|_| None);
262	        let mut bases = [core::ptr::null_mut::<u8>(); MAX_SEGMENTS as usize];
263	        for seg in 0..seg_count as usize {
264	            match pool.alloc_bytes() {
265	                Ok(buf) => {
266	                    bases[seg] = buf.as_mut_ptr();
267	                    taken[seg] = Some(buf);
268	                }
269	                Err(_) => {
270	                    taken.into_iter().flatten().for_each(crate::BufSlot::free);
271	                    return Err(Error::Exhausted);
272	                }
273	            }
274	        }
275	        // The segments stay allocated: their guards go out of
276	        // scope with `taken`, never freed.
277	        let mut slots = [core::ptr::null_mut(); MAX_SEGMENTS as usize];
278	        let mut headers = [core::ptr::null(); MAX_SEGMENTS as usize];
279	        for (seg, &base) in bases.iter().take(seg_count as usize).enumerate() {
280	            // SAFETY: base is a buffer of at least segment_size
281	            // bytes the pool just handed out, line-aligned, and
282	            // nothing else can reach it until the ring is split:
283	            // the header lines and each slot's header are ours to
284	            // write.
285	            unsafe {
286	                core::ptr::write_bytes(base, 0, size_of::<SegmentHeader>());
287	                let seg_slots = base.add(size_of::<SegmentHeader>());
288	                for i in 0..seg_capacity {
289	                    let slot = seg_slots.add(i as usize * slot_size as usize);
290	                    core::ptr::write_bytes(slot, 0, SLOT_HEADER_BYTES);
291	                    // `seq[i] = i`: every slot claimable for lap 0.
292	                    (*(slot as *const AtomicU32)).store(seq_of(i), Ordering::Relaxed);
293	                }
294	                slots[seg] = seg_slots;
295	                headers[seg] = base as *const SegmentHeader;
296	            }
297	        }
298	        let segs = Segments {
299	            slots,
300	            headers,
301	            slot_size,
302	            capacity: seg_capacity,
303	            mask: seg_capacity - 1,
304	            seg_count,
305	            commit_add: seg_capacity + 1,
306	        };
307	        // The ring starts in segment 0 at position 0, segment 0
308	        // in use. The threads that use the ring start after this,
309	        // so Relaxed is enough here.
310	        segs.claim().store(word(0, 0), Ordering::Relaxed);
311	        segs.in_use().store(1, Ordering::Relaxed);
312	        Ok(MpscRing {
313	            segs,
314	            _region: PhantomData,
315	        })
316	    }
317	
318	    /// Split into one producer handle and the consumer handle.
319	    ///
320	    /// - The producer is `Clone`: one clone per producing thread,
321	    ///   or one handle shared by reference. The consumer is
322	    ///   unique.
323	    pub fn split(self) -> (MpscProducer<'a>, MpscConsumer<'a>) {
324	        (MpscProducer::new(self.segs), MpscConsumer::new(self.segs))
325	    }
326	}
327	
328	#[cfg(test)]
329	mod tests {
330	    use super::*;
331	    use crate::{Empty, Exhausted, Full, PoolHeader};
332	    use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};
333	
334	    /// Test message, two words so a torn write would be visible.
335	    #[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Debug, PartialEq)]
336	    #[repr(C)]
337	    struct Msg {
338	        seq: u64,
339	        val: u64,
340	    }
341	
342	    /// Test pool buffer: a segment of up to 16 one-line slots.
343	    const BUF: usize = 3 * CACHE_LINE_SIZE + 16 * CACHE_LINE_SIZE;
344	
345	    /// Buffers in the test pool.
346	    const BUFS: usize = 8;
347	
348	    /// Backing store for the tests' pools.
349	    #[repr(C, align(64))]
350	    struct Region([u8; size_of::<PoolHeader>() + BUFS * BUF]);
351	
352	    impl Region {
353	        fn new() -> Box<Self> {
354	            Box::new(Region([0; size_of::<PoolHeader>() + BUFS * BUF]))
355	        }
356	    }
357	
358	    /// Send `from..to` as `seq = i`, `val = i * 10`.
359	    fn send(prod: &MpscProducer<'_>, from: u64, to: u64) {
360	        for i in from..to {
361	            prod.send_with::<Msg>(
362	                |_| false,
363	                |m| {
364	                    m.seq = i;
365	                    m.val = i * 10;
366	                },
367	            )
368	            .unwrap();
369	        }
370	    }
371	
372	    /// Receive `from..to` in order.
373	    fn recv(cons: &mut MpscConsumer<'_>, from: u64, to: u64) {
374	        for i in from..to {
375	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
376	            assert_eq!(
377	                *msg,
378	                Msg {
379	                    seq: i,
380	                    val: i * 10
381	                }
382	            );
383	            msg.release();
384	        }
385	    }
386	
387	    /// Segments free by the in-use word.
388	    fn free_segments(prod: &MpscProducer<'_>) -> u32 {
389	        let segs = &prod.segs;
390	        !segs.in_use().load(Ordering::Acquire) & segs.all()
391	    }
392	
393	    #[test]
394	    fn init_rejects_bad_geometry() {
395	        let mut r = Region::new();
396	        let mut pool = Pool::init(&mut r.0, BUF as u32, BUFS as u32).unwrap();
397	        let err =
398	            |slot, cap, count, pool: &mut Pool<'_>| MpscRing::init(pool, slot, cap, count).err();
399	        assert_eq!(err(63, 4, 2, &mut pool), Some(Error::BadSlotSize));
400	        assert_eq!(err(0, 4, 2, &mut pool), Some(Error::BadSlotSize));

