14	/// A producing handle: `Clone` one per producing thread, then
15	/// `send_with`.
16	///
17	/// - `send_with` takes `&self`: exclusivity comes from the claim
18	///   CAS, not the borrow, so one handle may also be shared by
19	///   reference.
20	pub struct MpscProducer<'a> {
21	    /// Geometry and segment addresses.
22	    pub(super) segs: Segments,
23	    _region: PhantomData<&'a [u8]>,
24	}
25	
26	impl Clone for MpscProducer<'_> {
27	    /// A second producing handle over the same ring, and the claim
28	    /// CAS serializes them.
29	    fn clone(&self) -> Self {
30	        MpscProducer { ..*self }
31	    }
32	}
33	
34	// SAFETY: any number of producers is the protocol contract: the
35	// shared state (the header words, the slot seqs) is atomic, slot
36	// claims are exclusive by CAS, and slot writes are handed off
37	// with Release/Acquire ordering.
38	unsafe impl Send for MpscProducer<'_> {}
39	// SAFETY: send_with is &self and every access is protected as
40	// above, so shared references across threads are equally fine.
41	unsafe impl Sync for MpscProducer<'_> {}
42	
43	/// Commits-on-drop guard armed while the fill closure runs: a
44	/// panic unwinding through `send_with` must not abandon the
45	/// claimed position, so drop-without-disarm publishes the
46	/// tombstoned commit the consumer releases without delivering.
47	struct TombstoneOnUnwind<'s> {
48	    /// The claimed slot's seq word.
49	    seq: &'s AtomicU32,
50	    /// The commit value (`pos + M + 1`).
51	    commit: u32,
52	}
53	
54	impl Drop for TombstoneOnUnwind<'_> {
55	    /// Unwind path only, and the normal path disarms with
56	    /// `mem::forget`.
57	    fn drop(&mut self) {
58	        self.seq.store(self.commit | TOMBSTONE, Ordering::Release);
59	    }
60	}
61	
62	/// Why a switch attempt did not move the ring.
63	enum NoSwitch {
64	    /// No segment is free: the ring is Full.
65	    NoFree,
66	    /// The claim word moved under the attempt: another producer
67	    /// switched, or the slot was released and claimed.
68	    Lost,
69	}
70	
71	impl<'a> MpscProducer<'a> {
72	    /// Build the handle from [`MpscRing::split`](super::MpscRing::split)'s
73	    /// geometry snapshot.
74	    pub(super) fn new(segs: Segments) -> Self {
75	        MpscProducer {
76	            segs,
77	            _region: PhantomData,
78	        }
79	    }
80	
81	    /// Segment switches the ring's producers have made: how many
82	    /// times a producer at a full segment moved the ring to a
83	    /// free one. Once the consumer has read everything sent, it
84	    /// equals the consumer's count.
85	    pub fn switches(&self) -> u64 {
86	        self.segs.switches().load(Ordering::Relaxed) as u64
87	    }
88	
89	    /// The segment the ring's producers write into, `0` to the
90	    /// ring's segment count less one.
91	    pub fn segment(&self) -> u32 {
92	        word_seg(self.segs.claim().load(Ordering::Relaxed))
93	    }
94	
95	    /// Claim the next position, fill it in place, commit on
96	    /// closure return, and retry a full ring under the injected wait
97	    /// policy, then [`Full`].
98	    ///
99	    /// - `fill` writes the message through `&mut T`, and commit is by
100	    ///   construction, so there is no abandonment state. If `fill`
101	    ///   panics, the unwind publishes a tombstoned commit the
102	    ///   consumer skips.
103	    /// - `on_full` is called after each failed attempt with the
104	    ///   attempt count (0-based, saturating), and returning `false`
105	    ///   gives up. Pass `|_| false` for a single non-blocking
106	    ///   probe. Full means the current segment's next slot is
107	    ///   unread and no segment is free.
108	    /// - Losing a claim race, or a switch race, is not a policy
109	    ///   call: the ring made progress, and this producer retries
110	    ///   with the fresher claim word.
111	    /// - `T` must fit the slot body, `slot_size` less
112	    ///   [`SLOT_HEADER_BYTES`](super::SLOT_HEADER_BYTES), at an
113	    ///   alignment of at most that.
114	    pub fn send_with<T>(
115	        &self,
116	        mut on_full: impl FnMut(u32) -> bool,
117	        fill: impl FnOnce(&mut T),
118	    ) -> Result<(), Full>
119	    where
120	        T: FromBytes + IntoBytes + KnownLayout,
121	    {
122	        let segs = &self.segs;
123	        check_body_type::<T>(segs.slot_size);
124	        let claim = segs.claim();
125	        // SeqCst on every claim word access, as v1's index: the
126	        // claim is only exclusive if these are linearizable.
127	        let mut w = claim.load(Ordering::SeqCst);
128	        let mut attempt = 0u32;
129	        let (seg, pos) = loop {
130	            let seg = word_seg(w);
131	            let pos = word_pos(w);
132	            if seg >= segs.seg_count {
133	                // A scribbled claim word: the ring is wedged, and
134	                // this degrades toward Full, never toward a slot
135	                // the ring does not have.
136	                return Err(Full);
137	            }
138	            // Acquire pairs with the consumer's Release in
139	            // release(): a claimable seq means the previous lap's
140	            // reads are done.
141	            let seq = segs.seq(seg, pos).load(Ordering::Acquire);
142	            if seq == pos {
143	                // Claimable. Weak CAS: a spurious failure just
144	                // retries with the fresher word.
145	                match claim.compare_exchange_weak(
146	                    w,
147	                    word(seg, pos.wrapping_add(1)),
148	                    Ordering::SeqCst,
149	                    Ordering::SeqCst,
150	                ) {
151	                    Ok(_) => break (seg, pos),
152	                    Err(actual) => w = actual,
153	                }
154	                continue;
155	            }
156	            // Not claimable at pos: a stale word or a full
157	            // segment, told apart by re-reading, as v1 does.
158	            let cur = claim.load(Ordering::SeqCst);
159	            if cur != w {
160	                w = cur;
161	                continue;
162	            }
163	            match self.switch(w) {
164	                Ok(()) | Err(NoSwitch::Lost) => {}
165	                Err(NoSwitch::NoFree) => {
166	                    if !on_full(attempt) {
167	                        return Err(Full);
168	                    }
169	                    attempt = attempt.saturating_add(1);
170	                }
171	            }
172	            w = claim.load(Ordering::SeqCst);
173	        };
174	        // (seg, pos) is exclusively ours until the seq commit
175	        // store.
176	        let msg = segs.body(seg, pos) as *mut T;
177	        let commit = seq_of(pos.wrapping_add(segs.commit_add));
178	        let guard = TombstoneOnUnwind {
179	            seq: segs.seq(seg, pos),
180	            commit,
181	        };
182	        // SAFETY: msg is in-bounds and aligned (check_body_type
183	        // against the body's offset in a line-aligned slot), any
184	        // byte pattern is a valid T (FromBytes bound), and the
185	        // claim CAS gives exclusive slot access until the commit
186	        // store below.
187	        fill(unsafe { &mut *msg });
188	        // Normal path: disarm the unwind guard, then publish.
189	        let seq = guard.seq;
190	        core::mem::forget(guard);
191	        // Release pairs with the consumer's Acquire seq load:
192	        // observing pos + M + 1 means the filled bytes are
193	        // visible.
194	        seq.store(commit, Ordering::Release);
195	        Ok(())
196	    }
197	
198	    /// Move the ring from the full segment and position `w` names
199	    /// to a free segment.
200	    ///
201	    /// - Take the lowest free segment by setting its bit in the
202	    ///   in-use word, which serializes producers switching at
203	    ///   once and succeeds only where the bit was clear, clear its
204	    ///   seal, and CAS the claim word from `w` to the new segment
205	    ///   at its resume position, the position its seal held.
206	    /// - On success, seal the old segment: MOVED, the new segment,
207	    ///   and `w`'s position as the end. Every claim in the old
208	    ///   segment lies before it.
209	    /// - On a lost claim CAS, restore the seal and clear the bit:
210	    ///   the ring moved under the attempt, and the caller retries
211	    ///   with the fresh word.
212	    fn switch(&self, w: u32) -> Result<(), NoSwitch> {
213	        let segs = &self.segs;
214	        let in_use = segs.in_use();
215	        loop {
216	            // Acquire: a consumer's give-back is visible with its
217	            // released seqs.
218	            let free = !in_use.load(Ordering::Acquire) & segs.all();
219	            if free == 0 {
220	                return Err(NoSwitch::NoFree);
221	            }
222	            let k = free.trailing_zeros();
223	            if in_use.fetch_or(1 << k, Ordering::AcqRel) & (1 << k) != 0 {
224	                // Another producer set it first.
225	                continue;
226	            }
227	            // Segment k is ours among producers, and the consumer
228	            // cannot enter it until a seal names it, so nobody else
229	            // reads or writes its seal here.
230	            let seal = segs.seal(k);
231	            let start = word_pos(seal.load(Ordering::Acquire));
232	            // Cleared before the claim CAS: a clear after it could
233	            // land after a later producer's seal of k, once the ring
234	            // has filled k and left it again, and wipe that seal.
235	            seal.store(0, Ordering::Relaxed);
236	            match segs.claim().compare_exchange(
237	                w,
238	                word(k, start),
239	                Ordering::SeqCst,
240	                Ordering::SeqCst,
241	            ) {
242	                Ok(_) => {
243	                    // Release pairs with the consumer's Acquire seal
244	                    // load: seeing MOVED means k's seal is clear.
245	                    segs.seal(word_seg(w))
246	                        .store(MOVED | word(k, word_pos(w)), Ordering::Release);
247	                    segs.switches().fetch_add(1, Ordering::Relaxed);
248	                    return Ok(());
249	                }
250	                Err(_) => {
251	                    // Put k back as it was: its resume position for
252	                    // the next taker, then its bit.
253	                    seal.store(start, Ordering::Relaxed);
254	                    in_use.fetch_and(!(1 << k), Ordering::AcqRel);
255	                    return Err(NoSwitch::Lost);
256	                }
257	            }
258	        }
259	    }
260	}
