651	/// A ring of segments over the application's pool, its two roles
652	/// claimed with [`Ring::claim_producer`] and
653	/// [`Ring::claim_consumer`].
654	pub struct Ring<'a> {
655	    /// Geometry and segment offsets.
656	    segs: Segments,
657	    /// The pool buffer index of segment 0, where the control
658	    /// block is.
659	    first_segment: u32,
660	    _region: core::marker::PhantomData<&'a [u8]>,
661	}
662	
663	impl<'a> Ring<'a> {
664	    /// Take `seg_count` segments from `pool` and initialize each
665	    /// as an empty ring of `seg_capacity` slots of `slot_size`
666	    /// bytes.
667	    ///
668	    /// - `slot_size`: N bytes per slot, a [`CACHE_LINE_SIZE`]
669	    ///   multiple, of which [`SLOT_HEADER_BYTES`] are the crate's.
670	    /// - `seg_capacity`: M slots per segment, a power of two up to
671	    ///   [`MAX_SEG_CAPACITY`], 1 included.
672	    /// - `seg_count`: 1 to [`MAX_SEGMENTS`].
673	    /// - The pool's buffers must hold [`segment_size`], else
674	    ///   [`Error::TooSmall`]. A pool without `seg_count` free
675	    ///   buffers gives [`Error::Exhausted`], with the buffers
676	    ///   taken so far freed.
677	    /// - The pool is borrowed only here. The segments stay
678	    ///   allocated for the life of the pool region, as a
679	    ///   [`BufSlot`](crate::BufSlot) dropped without `free` does.
680	    /// - Every segment's header names the ring, and segment 0's
681	    ///   holds the table of segments, so a process holding the
682	    ///   pool and [`first_segment`](Ring::first_segment) can find
683	    ///   the ring.
684	    pub fn init(
685	        pool: &mut Pool<'a>,
686	        slot_size: u32,
687	        seg_capacity: u32,
688	        seg_count: u32,
689	    ) -> Result<Self, Error> {
690	        validate_geometry(slot_size, seg_capacity, seg_count)?;
691	        if (pool.buf_size() as u64) < segment_size(slot_size, seg_capacity) {
692	            return Err(Error::TooSmall);
693	        }
694	        let mut taken: [Option<crate::BufSlot<'a, [u8]>>; MAX_SEGMENTS as usize] =
695	            core::array::from_fn(|_| None);
696	        let mut indices = [NO_SEGMENT; MAX_SEGMENTS as usize];
697	        for seg in 0..seg_count as usize {
698	            match pool.alloc_bytes() {
699	                Ok(buf) => {
700	                    indices[seg] = buf.idx();
701	                    taken[seg] = Some(buf);
702	                }
703	                Err(_) => {
704	                    taken.into_iter().flatten().for_each(crate::BufSlot::free);
705	                    return Err(Error::Exhausted);
706	                }
707	            }
708	        }
709	        // The segments stay allocated: their guards go out of
710	        // scope with `taken`, never freed.
711	        let base = pool.bufs_ptr();
712	        let buf_size = pool.buf_size() as usize;
713	        for seg in 0..seg_count as usize {
714	            let offset = indices[seg] as usize * buf_size;
715	            // SAFETY: the offset names a buffer of at least
716	            // segment_size bytes the pool just handed out,
717	            // line-aligned, and nothing else can reach it until a
718	            // role is taken: the header lines and each slot's
719	            // header are ours to write.
720	            unsafe {
721	                let seg_base = base.add(offset);
722	                core::ptr::write_bytes(seg_base, 0, size_of::<SegmentHeader>());
723	                let header = &*(seg_base as *const SegmentHeader);
724	                header
725	                    .info
726	                    .layout_version
727	                    .store(LAYOUT_VERSION, Ordering::Relaxed);
728	                header.info.slot_size.store(slot_size, Ordering::Relaxed);
729	                header
730	                    .info
731	                    .seg_capacity
732	                    .store(seg_capacity, Ordering::Relaxed);
733	                header.info.seg_count.store(seg_count, Ordering::Relaxed);
734	                header.info.seg_num.store(seg as u32, Ordering::Relaxed);
735	                if seg == 0 {
736	                    for (entry, &idx) in header.table.iter().zip(indices.iter()) {
737	                        entry.store(idx, Ordering::Relaxed);
738	                    }
739	                    // The producer starts holding segment 0, so its
740	                    // checkpoint does too.
741	                    header.claims.prod_taken.store(1, Ordering::Relaxed);
742	                }
743	                let seg_slots = seg_base.add(size_of::<SegmentHeader>());
744	                for i in 0..seg_capacity {
745	                    let slot = seg_slots.add(i as usize * slot_size as usize);
746	                    core::ptr::write_bytes(slot, 0, SLOT_HEADER_BYTES);
747	                    // `seq[i] = i`: every slot claimable for lap 0.
748	                    (*(slot as *const AtomicU32)).store(seq_of(i), Ordering::Relaxed);
749	                }
750	                // The magic last (Release): a reader that sees it
751	                // sees the rest of the block.
752	                header.info.magic.store(MAGIC, Ordering::Release);
753	            }
754	        }
755	        Ok(Ring {
756	            segs: Segments::load(base, buf_size, &indices, slot_size, seg_capacity, seg_count),
757	            first_segment: indices[0],
758	            _region: core::marker::PhantomData,
759	        })
760	    }
761	
762	    /// Join a ring another process (or an earlier call) initialized
763	    /// over `pool`, from the pool buffer index of its segment 0.
764	    ///
765	    /// - Reads the control block, checks every field and every
766	    ///   table entry against the pool's geometry, and every
767	    ///   segment's own header against the block, so a hostile
768	    ///   region is an `Err`, never an out-of-bounds access.
769	    /// - A role claimed from the attached ring starts where the
770	    ///   role's state says: at the start for a role never claimed,
771	    ///   where it stopped for a released one, and from the last
772	    ///   switch for one taken over.
773	    ///
774	    /// # Safety
775	    ///
776	    /// - `first_segment` came from [`first_segment`](Ring::first_segment)
777	    ///   of a ring initialized over this pool's region, and its
778	    ///   segments are still the ring's: validation cannot tell a
779	    ///   ring's segment from a buffer since freed and reused, and
780	    ///   the ring writes seq words into every segment it is told
781	    ///   it has.
782	    pub unsafe fn attach(pool: &Pool<'a>, first_segment: u32) -> Result<Self, Error> {
783	        let buf_count = pool.buf_count();
784	        if first_segment >= buf_count {
785	            return Err(Error::BadSegment);
786	        }
787	        let base = pool.bufs_ptr();
788	        let buf_size = pool.buf_size() as usize;
789	        // SAFETY: first_segment < buf_count, so the header is the
790	        // line-aligned front of a buffer inside the pool's region,
791	        // and every field read is atomic.
792	        let block =
793	            unsafe { &*(base.add(first_segment as usize * buf_size) as *const SegmentHeader) };
794	        // Acquire pairs with init's Release store of the magic.
795	        if block.info.magic.load(Ordering::Acquire) != MAGIC {
796	            return Err(Error::BadMagic);
797	        }
798	        if block.info.layout_version.load(Ordering::Relaxed) != LAYOUT_VERSION {
799	            return Err(Error::BadLayoutVersion);
800	        }
801	        let slot_size = block.info.slot_size.load(Ordering::Relaxed);
802	        let seg_capacity = block.info.seg_capacity.load(Ordering::Relaxed);
803	        let seg_count = block.info.seg_count.load(Ordering::Relaxed);
804	        validate_geometry(slot_size, seg_capacity, seg_count)?;
805	        if (buf_size as u64) < segment_size(slot_size, seg_capacity) {
806	            return Err(Error::TooSmall);
807	        }
808	        if block.info.seg_num.load(Ordering::Relaxed) != 0 {
809	            return Err(Error::BadSegment);
810	        }
811	        let mut indices = [NO_SEGMENT; MAX_SEGMENTS as usize];
812	        for seg in 0..seg_count as usize {
813	            let idx = block.table[seg].load(Ordering::Relaxed);
814	            if idx >= buf_count || indices[..seg].contains(&idx) {
815	                return Err(Error::BadSegment);
816	            }
817	            indices[seg] = idx;
818	        }
819	        if indices[0] != first_segment {
820	            return Err(Error::BadSegment);
821	        }
822	        // Every segment's own header must agree with the block.
823	        for (seg, &idx) in indices.iter().enumerate().take(seg_count as usize) {
824	            // SAFETY: idx < buf_count, as checked above.
825	            let info =
826	                unsafe { &(*(base.add(idx as usize * buf_size) as *const SegmentHeader)).info };
827	            let agrees = info.magic.load(Ordering::Acquire) == MAGIC
828	                && info.layout_version.load(Ordering::Relaxed) == LAYOUT_VERSION
829	                && info.slot_size.load(Ordering::Relaxed) == slot_size
830	                && info.seg_capacity.load(Ordering::Relaxed) == seg_capacity
831	                && info.seg_count.load(Ordering::Relaxed) == seg_count
832	                && info.seg_num.load(Ordering::Relaxed) == seg as u32;
833	            if !agrees {
834	                return Err(Error::BadSegment);
835	            }
836	        }
837	        Ok(Ring {
838	            segs: Segments::load(base, buf_size, &indices, slot_size, seg_capacity, seg_count),
839	            first_segment,
840	            _region: core::marker::PhantomData,
841	        })
842	    }
