pub(crate) fn check_body_type<T>(slot_size: u32) {
    assert!(
        size_of::<T>() <= slot_size as usize - SLOT_HEADER_BYTES,
        "T larger than the slot body"
    );
    assert!(
        align_of::<T>() <= SLOT_HEADER_BYTES,
        "T alignment exceeds the slot body's"
    );
}

