728	    /// `producers` threads each sending `count` messages through
729	    /// `seg_count` segments of `cap` slots, spinning on both ends,
730	    /// per-producer FIFO checked at the consumer.
731	    fn stream(producers: u64, cap: u32, seg_count: u32, count: u64) {
732	        let mut r = Region::new();
733	        let mut pool = Pool::init(&mut r.0, BUF as u32, BUFS as u32).unwrap();
734	        let (prod, mut cons) = MpscRing::init(&mut pool, 64, cap, seg_count)
735	            .unwrap()
736	            .split();
737	        std::thread::scope(|s| {
738	            for p in 0..producers {
739	                let prod = prod.clone();
740	                s.spawn(move || {
741	                    for i in 0..count {
742	                        prod.send_with::<Msg>(crate::policy::spin, |m| {
743	                            m.seq = i;
744	                            m.val = p;
745	                        })
746	                        .unwrap(); // OK: policy::spin never gives up
747	                    }
748	                });
749	            }
750	            let cons = &mut cons;
751	            s.spawn(move || {
752	                // Global arrival order is claim order, and only
753	                // per-producer FIFO is promised.
754	                let mut next = vec![0u64; producers as usize];
755	                for _ in 0..producers * count {
756	                    let msg = cons.reserve_slot_with::<Msg>(crate::policy::spin).unwrap(); // OK: policy::spin never gives up
757	                    let p = msg.val as usize;
758	                    assert_eq!(msg.seq, next[p], "per-producer order broken");
759	                    next[p] += 1;
760	                    msg.release();
761	                }
762	                assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
763	            });
764	        });
765	        // Every seal was consumed once, and every segment but the
766	        // current one is back.
767	        assert_eq!(cons.switches(), prod.switches());
768	        assert_eq!(free_segments(&prod).count_ones(), seg_count - 1);
769	        assert_eq!(prod.segment(), cons.segment());
770	    }
