772	    /// One cache line of heap backing store, so a `Vec` of them is
773	    /// a line-aligned region of any size.
774	    #[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Clone)]
775	    #[repr(C, align(64))]
776	    struct Line([u8; CACHE_LINE_SIZE]);
777	
778	    /// The segment counts, depths, and producer counts the matrix
779	    /// covers: all of them, or under Miri a corner, its
780	    /// interpreter being slow.
781	    fn matrix() -> (Vec<u32>, Vec<u32>, Vec<u64>) {
782	        if cfg!(miri) {
783	            (vec![1, 2, 32], vec![1, 8], vec![1, 2])
784	        } else {
785	            (
786	                (1..=MAX_SEGMENTS).collect(),
787	                vec![1, 8, 64, 1024],
788	                vec![1, 2, 4],
789	            )
790	        }
791	    }
792	
793	    /// Run `f` on a ring of `count` segments of `depth` one-line
794	    /// slots over a pool holding exactly those segments.
795	    fn with_ring(count: u32, depth: u32, f: impl FnOnce(MpscProducer<'_>, MpscConsumer<'_>)) {
796	        let buf = segment_size(64, depth);
797	        let bytes = size_of::<PoolHeader>() as u64 + buf * count as u64;
798	        let mut store = vec![Line([0; CACHE_LINE_SIZE]); bytes.div_ceil(64) as usize];
799	        let mut pool = Pool::init(store.as_mut_slice().as_mut_bytes(), buf as u32, count).unwrap();
800	        let (prod, cons) = MpscRing::init(&mut pool, 64, depth, count).unwrap().split();
801	        f(prod, cons);
802	    }
