804	    #[test]
805	    fn every_count_and_depth_fills_and_drains() {
806	        // With the consumer idle a producer writes into every
807	        // segment in turn, switching once between each pair, and
808	        // the consumer follows it through the same switches.
809	        let (counts, depths, _) = matrix();
810	        for &count in &counts {
811	            for &depth in &depths {
812	                with_ring(count, depth, |prod, mut cons| {
813	                    let total = (count * depth) as u64;
814	                    let mut used = 1u32 << prod.segment();
815	                    for i in 0..total {
816	                        send(&prod, i, i + 1);
817	                        used |= 1 << prod.segment();
818	                    }
819	                    assert_eq!(prod.send_with::<Msg>(|_| false, |_| {}).err(), Some(Full));
820	                    assert_eq!(
821	                        used.count_ones(),
822	                        count,
823	                        "{count} segments at depth {depth}"
824	                    );
825	                    assert_eq!(prod.switches(), (count - 1) as u64);
826	                    recv(&mut cons, 0, total);
827	                    assert_eq!(cons.reserve_slot_with::<Msg>(|_| false).err(), Some(Empty));
828	                    assert_eq!(cons.switches(), prod.switches());
829	                    assert_eq!(cons.segment(), prod.segment());
830	                    assert_eq!(free_segments(&prod).count_ones(), count - 1);
831	                });
832	            }
833	        }
834	    }
835	
836	    #[test]
837	    fn every_count_and_depth_survives_uneven_bursts() {
838	        // Bursts of every size up to the ring's capacity leave
839	        // segments mid-lap, and after each drain both ends agree.
840	        let (counts, depths, _) = matrix();
841	        let rounds = if cfg!(miri) { 5 } else { 40 };
842	        for &count in &counts {
843	            for &depth in &depths {
844	                with_ring(count, depth, |prod, mut cons| {
845	                    let capacity = (count * depth) as u64;
846	                    let mut next = 0u64;
847	                    for round in 0..rounds {
848	                        let n = 1 + (round * 7919) % capacity;
849	                        send(&prod, next, next + n);
850	                        recv(&mut cons, next, next + n);
851	                        next += n;
852	                        assert_eq!(cons.reserve_slot_with::<Msg>(|_| false).err(), Some(Empty));
853	                        assert_eq!(cons.switches(), prod.switches());
854	                        assert_eq!(free_segments(&prod).count_ones(), count - 1);
855	                    }
856	                });
857	            }
858	        }
859	    }
