macro_rules! spsc4_pair {
    ($producer:ident, $consumer:ident, $store:ident, $pool:ident, $depth:expr,
     segmented $segments:expr) => {
        spsc_pair!($producer, $consumer, $store, $pool, $depth, segmented_roles $segments);
    };
}

