/// One row of the segment stress table.
struct StressRow {
    /// The line: ring, shape, thread count.
    line: String,
    /// Where its threads sat.
    placement: String,
    /// Segments times depth.
    shape: String,
    /// Elapsed ns per message, `None` for a line paced by the
    /// consumer's pauses.
