    /// Segments the producer wrote into, of the ring's.
    used: (u32, u32),
    /// Switches the producer counted, the consumer agreeing.
    switches: u64,
    /// The cost of one switch in ns, on the row that measures
    /// it.
    switch_ns: Option<f64>,
        "-".repeat(7),
        "-".repeat(8),
        "-".repeat(6),
        "-".repeat(9),
        "-".repeat(7),
        "-".repeat(10)
    );
    for r in rows {
        println!(
            "| {:<17} | {:<16} | {:>6} | {:>7} | {:>5} | {:>8} | {:>6.3} | {:>9} |",
            r.line,
