            r.shape,
            r.ns.map_or("-".to_string(), |ns| format!("{ns:.1}")),
            format!("{}/{}", r.used.0, r.used.1),
            commas(r.switches),
            r.per_msg(),
            r.switch_ns.map_or("-".to_string(), |ns| format!("{ns:.1}")),
        );
