/// - The order keeps the claim word out of the seal's 128-byte
///   pair, whichever line the buffer starts on: the adjacent-line
///   prefetcher fetches lines in such pairs, and the consumer loads
///   the seal on its empty path, so a seal beside the claim word
///   pulled the producers' hottest line across cores on every
///   message it waited for. The claim word's partner is the table
///   or the in-use line, the seal's the info or the claims line,
///   none of them on the other side's message path.
/// - The pool buffer index of each segment is in the table, so a
///   process holding the pool and segment 0's index finds every
///   segment.
#[repr(C)]
struct SegmentHeader {
    /// Line 0: the ring's identity and geometry.
    info: CacheAligned<Info>,
    /// Line 1: the seal: MOVED, the next segment, and the end
    /// position, stored by the producer that moved the ring on,
    /// cleared by the producer that next takes this segment, and
    /// read by the consumer when a slot is not committed.
    seal: CacheAligned<AtomicU32>,
    /// Line 2, segment 0: the roles, the consumer's checkpoint, and
    /// the producers' wait words.
    claims: CacheAligned<Claims>,
    /// Lines 3 and 4, segment 0: the pool buffer index of segment
    /// `i` at `table[i]`, [`NO_SEGMENT`] past `seg_count`.
    table: CacheAligned<[AtomicU32; MAX_SEGMENTS as usize]>,
    /// Line 5, segment 0: the current segment and the next
    /// position to claim, CAS-claimed by every producer.
    claim: CacheAligned<AtomicU32>,
    /// Line 6, segment 0: the in-use word and the switch count,
    /// both touched on the switch path only.
    in_use: CacheAligned<InUseLine>,
}

