p="src/policy.rs"; s=open(p).read()
old="""/// Spin forever: hint the CPU and keep waiting.
///"""
new="""/// Back off after a lost claim race: `2^lost` spin hints, capped
/// at 64, for an MPSC v3 producer's
/// [`send_with_backoff`](crate::mpsc::v3::MpscProducer::send_with_backoff).
///
/// - Each producer that loses a claim CAS pauses before it reads the
///   claim word again, longer after each loss in a row, so fewer
///   cores pull the contended line at once and the winner's next
///   CAS lands sooner.
/// - `#[inline]` for the same reason as [`spin`].
#[inline]
pub fn backoff(lost: u32) {
    for _ in 0..1u32 << lost.min(6) {
        core::hint::spin_loop();
    }
}

/// Spin forever: hint the CPU and keep waiting.
///"""
assert old in s; s=s.replace(old,new,1); open(p,"w").write(s)

p="src/mpsc/v3/producer.rs"; s=open(p).read()
def rep(old,new):
    global s
    assert old in s, old[:80]; s=s.replace(old,new,1)
rep("""    {
        self.send(on_full, fill, false)
    }

    /// [`send_with`](MpscProducer::send_with), sleeping on a full""","""    {
        self.send(on_full, |_| {}, fill, false)
    }

    /// [`send_with`](MpscProducer::send_with), calling `on_lost`
    /// after each claim race this producer loses, with the count of
    /// losses in a row, 1 for the first.
    ///
    /// - A lost race is no policy call in `send_with`: the ring made
    ///   progress, and the loser reads the claim word again at once.
    ///   With many producers that read pulls the contended line from
    ///   the winner on every loss, so `on_lost` is where a producer
    ///   backs off, [`policy::backoff`](crate::policy::backoff) the
    ///   model.
    pub fn send_with_backoff<T>(
        &self,
        on_full: impl FnMut(u32) -> bool,
        on_lost: impl FnMut(u32),
        fill: impl FnOnce(&mut T),
    ) -> Result<(), Full>
    where
        T: FromBytes + IntoBytes + KnownLayout,
    {
        self.send(on_full, on_lost, fill, false)
    }

    /// [`send_with`](MpscProducer::send_with), sleeping on a full""")
rep("""    {
        self.send(on_full, fill, true)
    }""","""    {
        self.send(on_full, |_| {}, fill, true)
    }""")
rep("""    fn send<T>(
        &self,
        mut on_full: impl FnMut(u32) -> bool,
        fill: impl FnOnce(&mut T),
        sleep: bool,
    ) -> Result<(), Full>""","""    fn send<T>(
        &self,
        mut on_full: impl FnMut(u32) -> bool,
        mut on_lost: impl FnMut(u32),
        fill: impl FnOnce(&mut T),
        sleep: bool,
    ) -> Result<(), Full>""")
rep("""        let mut attempt = 0u32;
        let (seg, pos) = loop {""","""        let mut attempt = 0u32;
        let mut lost = 0u32;
        let (seg, pos) = loop {""")
rep("""                    Err(actual) => w = actual,""","""                    Err(actual) => {
                        w = actual;
                        lost = lost.saturating_add(1);
                        on_lost(lost);
                    }""")
rep("""    /// The send both entries share, sleeping on a full ring when
    /// `sleep` is set.""","""    /// The send the entries share, calling `on_lost` after each
    /// lost claim race and sleeping on a full ring when `sleep` is
    /// set.""")
open(p,"w").write(s)
EOF
